import os
import sys
import secrets
from starlette.middleware.base import BaseHTTPMiddleware
from starlette.responses import JSONResponse
from fastapi import Request

IS_PRODUCTION = os.getenv("ENVIRONMENT", "development").lower() == "production"
CSRF_SECRET = os.getenv("CSRF_SECRET")
if not CSRF_SECRET:
    if IS_PRODUCTION:
        sys.exit("FATAL: CSRF_SECRET environment variable is not set. Production startup aborted to prevent insecure fallback.")
    else:
        CSRF_SECRET = "dev_insecure_csrf_secret_for_local_testing_only"

SAFE_METHODS = {"GET", "HEAD", "OPTIONS", "TRACE"}
EXEMPT_PATHS = {
    "/api/auth/login",
    "/api/auth/register",
    "/api/auth/token",
    "/api/health",
    "/docs",
    "/openapi.json"
}

class CSRFMiddleware(BaseHTTPMiddleware):
    async def dispatch(self, request: Request, call_next):
        if request.method in SAFE_METHODS or any(request.url.path.startswith(p) for p in EXEMPT_PATHS):
            response = await call_next(request)
            # Ensure CSRF cookie is set on safe responses
            if "csrf_token" not in request.cookies:
                token = secrets.token_urlsafe(32)
                response.set_cookie(
                    key="csrf_token",
                    value=token,
                    httponly=False,
                    samesite="lax",
                    secure=IS_PRODUCTION
                )
            return response

        # Verify Double-Submit CSRF Token on mutating endpoints
        cookie_token = request.cookies.get("csrf_token")
        header_token = request.headers.get("X-CSRF-Token")

        if not cookie_token or not header_token or not secrets.compare_digest(cookie_token, header_token):
            return JSONResponse(
                status_code=403,
                content={"detail": "CSRF validation failed. Missing or mismatched double-submit token."}
            )

        return await call_next(request)

