}

@router.get('/search')
async def admin_universal_search(
    q: str,
    admin: User = Depends(require_admin),
    db: Session = Depends(get_db)
):
    """Universal search across users, telemetry, failed jobs, and flags."""
    users = db.query(User).filter(User.email.contains(q)).limit(10).all()
    return {
        'query': q,
        'users': [{'id': u.id, 'email': u.email, 'role': getattr(u, 'role', 'user')} for u in users],
        'system_status': 'HEALTHY'
    }

